using FuelMind.Desktop.Dtos.Operations;
namespace FuelMind.Desktop.Services;
public interface IOperationsService { Task<IReadOnlyList<AttendantDto>> AttendantsAsync(CancellationToken ct=default); Task<AttendantDto> SaveAttendantAsync(int? id, AttendantSaveDto dto, CancellationToken ct=default); Task DeactivateAttendantAsync(int id, CancellationToken ct=default); Task<IReadOnlyList<ShiftDto>> ShiftsAsync(CancellationToken ct=default); Task<ShiftDto> SaveShiftAsync(int? id, ShiftSaveDto dto, CancellationToken ct=default); Task DeactivateShiftAsync(int id, CancellationToken ct=default); Task AssignAsync(AssignmentSaveDto dto, CancellationToken ct=default); Task<IReadOnlyList<AssignmentDto>> AssignmentsAsync(CancellationToken ct=default); Task<AssignmentDto> SetAssignmentActiveAsync(int id,bool active,CancellationToken ct=default); }
public sealed class OperationsService(ApiClient api) : IOperationsService { public Task<IReadOnlyList<AttendantDto>> AttendantsAsync(CancellationToken ct=default)=>api.GetAsync<IReadOnlyList<AttendantDto>>("attendants",ct); public Task<AttendantDto> SaveAttendantAsync(int? id,AttendantSaveDto d,CancellationToken ct=default)=>id is int x?api.PutAsync<AttendantSaveDto,AttendantDto>($"attendants/{x}",d,ct):api.PostAsync<AttendantSaveDto,AttendantDto>("attendants",d,ct); public Task DeactivateAttendantAsync(int id,CancellationToken ct=default)=>api.DeleteAsync($"attendants/{id}",ct); public Task<IReadOnlyList<ShiftDto>> ShiftsAsync(CancellationToken ct=default)=>api.GetAsync<IReadOnlyList<ShiftDto>>("shifts",ct); public Task<ShiftDto> SaveShiftAsync(int? id,ShiftSaveDto d,CancellationToken ct=default)=>id is int x?api.PutAsync<ShiftSaveDto,ShiftDto>($"shifts/{x}",d,ct):api.PostAsync<ShiftSaveDto,ShiftDto>("shifts",d,ct); public Task DeactivateShiftAsync(int id,CancellationToken ct=default)=>api.DeleteAsync($"shifts/{id}",ct); public async Task AssignAsync(AssignmentSaveDto d,CancellationToken ct=default)=>_ = await api.PostAsync<AssignmentSaveDto,object>("attendant-shift-assignments",d,ct); public Task<IReadOnlyList<AssignmentDto>> AssignmentsAsync(CancellationToken ct=default)=>api.GetAsync<IReadOnlyList<AssignmentDto>>("attendant-shift-assignments",ct); public Task<AssignmentDto> SetAssignmentActiveAsync(int id,bool active,CancellationToken ct=default)=>api.PatchAsync<Dictionary<string,bool>,AssignmentDto>($"attendant-shift-assignments/{id}",new(){["is_active"]=active},ct); }
